/// <summary>
/// DebuC 16.10.23
/// </summary>
void initUms()
{
    this.Umsatz01   = 0;
    this.Umsatz02   = 0;
    this.Umsatz03   = 0;
    this.Umsatz04   = 0;
    this.Umsatz05   = 0;
    this.Umsatz06   = 0;
    this.Umsatz07   = 0;
    this.Umsatz08   = 0;
    this.Umsatz09   = 0;
    this.Umsatz10   = 0;
    this.Umsatz11   = 0;
    this.Umsatz02   = 0;
}

/// <summary>
/// DebuC 16.10.23
/// </summary>
/// <param name = "_NDX_TmpCSAlliance">NDXTmpCSAllianceMap</param>
/// <param name = "lExclude">boolean</param>
/// <param name = "lThread">boolean</param>
/// <param name = "lTestImport">boolean</param>
static void InitUmsCS(NDXTmpCSAllianceMap  _NDX_TmpCSAlliance,
                  boolean               lExclude,
                  boolean               lThread = false,
                  boolean               lTestImport = false)
{

    NDXTmpCSAllianceArtGrp     nDX_TmpCSAllianceArtGrp;

    NDXCompanyBE                 firma;
    NDXKdNr                    nDX_KdNr;
    ;
    firma       = NDXHelperCommon::CompanyId2NDXCompany(_NDX_TmpCSAlliance.Company, lTestImport);
    nDX_KdNr    = str2int(_NDX_TmpCSAlliance.CustAccount);

    try
    {
        // alle Einträge des Users löschen
        if (lThread)    // sonst Probleme mit Deadlock
        {
            while select forUpdate nDX_TmpCSAllianceArtGrp
            where       nDX_TmpCSAllianceArtGrp.UmsSignature        == _NDX_TmpCSAlliance.UmsSignature          &&
                        nDX_TmpCSAllianceArtGrp.MonthYearSignature  == _NDX_TmpCSAlliance.monthYearSignature    &&
                        nDX_TmpCSAllianceArtGrp.Exclude             == lExclude                                 &&
                        nDX_TmpCSAllianceArtGrp.Company             == _NDX_TmpCSAlliance.Company               &&
                        nDX_TmpCSAllianceArtGrp.Alliance            == _NDX_TmpCSAlliance.Alliance              &&
                        nDX_TmpCSAllianceArtGrp.CustAccount         == _NDX_TmpCSAlliance.CustAccount
            {
                ttsbegin;
                nDX_TmpCSAllianceArtGrp.delete();
                ttscommit;
            }

        }
        else
        {
            delete_from     nDX_TmpCSAllianceArtGrp
            where       nDX_TmpCSAllianceArtGrp.UmsSignature        == _NDX_TmpCSAlliance.UmsSignature          &&
                        nDX_TmpCSAllianceArtGrp.MonthYearSignature  == _NDX_TmpCSAlliance.monthYearSignature    &&
                        nDX_TmpCSAllianceArtGrp.Exclude             == lExclude                                 &&
                        nDX_TmpCSAllianceArtGrp.Company             == _NDX_TmpCSAlliance.Company               &&
                        nDX_TmpCSAllianceArtGrp.Alliance            == _NDX_TmpCSAlliance.Alliance              &&
                        nDX_TmpCSAllianceArtGrp.CustAccount         == _NDX_TmpCSAlliance.CustAccount;
        }
    }
    catch (exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= NDXConstants::RetryNum)
        {
            throw Exception::Deadlock;
        }
        else
        {
            retry;
        }
    }
}

/// <summary>
/// DebuC 16.10.23
/// last modified: PaffH 29.04.25
/// </summary>
/// <returns>NDXItemGroupBase</returns>
NDXItemGroupBase ArtGrp()
{
    NDXItemGroupBase artGrp = NDXArtGrpMap::find(this.ArtGrp).GruppeTo;
    if (!artGrp)
    {
        artGrp = this.ArtGrp;
    }
    if (!artGrp)
    {
        artGrp = strFmt("@NDXBase:NDXWithout");
    }
    return artGrp;
}

/// <summary>
/// DebuC 16.10.23
/// </summary>
/// <param name = "_FirmenNr">NDXCompanys</param>
/// <param name = "_KdNr">NDXKdNr</param>
/// <param name = "_ArtGrp">NDXItemGroup</param>
/// <param name = "_Jahr">NDXYear</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXKumUmsCustArtGrp</returns>
static NDXKumUmsCustArtGrp find(NDXCompanys     _FirmenNr,
                             NDXKdNr            _KdNr,
                             NDXItemGroup       _ArtGrp,
                             NDXYear            _Jahr,
                             boolean _forUpdate = false)
{
    NDXKumUmsCustArtGrp umsatz;
    ;
    umsatz.selectForUpdate(_forUpdate);

    if (_FirmenNr && _KdNr && _ArtGrp && _Jahr)
    {
        select umsatz
            where   umsatz.Companys == _FirmenNr    &&
                    umsatz.KdNr     == _KdNr        &&
                    umsatz.ARTGRP   == _ArtGrp      &&
                    umsatz.Jahr     == _Jahr;
    }

    return umsatz;
}

/// <summary>
/// DebuC 16.10.23
/// </summary>
/// <param name = "l_NDX_TmpCSAlliance">NDXTmpCSAlliance</param>
/// <param name = "jahr">NDXYear</param>
/// <param name = "lExclude">boolean</param>
/// <param name = "lAktJahr">boolean</param>
/// <param name = "lTestImport">boolean</param>
static void getUmsCS(NDXTmpCSAlliance  l_NDX_TmpCSAlliance,
                 NDXYear            jahr,
                 boolean            lExclude,
                 boolean            lAktJahr = true,
                 boolean            lTestImport = false)
{
    NDXKumUmsCustArtGrp        nDX_KumUmsCustArtGrp;
    NDXTmpCSAllianceArtGrp     nDX_TmpCSAllianceArtGrp;

    NDXCompanyBE                firma;
    NDXKdNr                     nDX_KdNr;

    Query                       q;
    QueryRun                    qr;
    QueryBuildDataSource        qbds;
    RecordSortedList            recordSortedList;

    ttsbegin;
    recordSortedList = new RecordSortedList(tablenum(NDXTmpCSAllianceArtGrp));
    recordSortedList.sortOrder(fieldnum(NDXTmpCSAllianceArtGrp, UmsSignature),
                           fieldnum(NDXTmpCSAllianceArtGrp, MonthYearSignature),
                           fieldnum(NDXTmpCSAllianceArtGrp, Exclude),
                           fieldnum(NDXTmpCSAllianceArtGrp, Company),
                           fieldnum(NDXTmpCSAllianceArtGrp, Alliance),
                           fieldnum(NDXTmpCSAllianceArtGrp, CustAccount),
                           fieldnum(NDXTmpCSAllianceArtGrp, CentralStoreId),
                           fieldnum(NDXTmpCSAllianceArtGrp, ArtGrp));

    firma       = NDXHelperCommon::CompanyId2NDXCompany(l_NDX_TmpCSAlliance.Company, lTestImport);
    nDX_KdNr    = str2int(l_NDX_TmpCSAlliance.CentralStoreId);

    // über alle Artikelgruppen des Zentrallagers die Werte ermitteln
    q       = new Query();
    qbds    = q.addDataSource(tablenum(NDXKumUmsCustArtGrp));
    qbds.addRange(fieldnum(NDXKumUmsCustArtGrp, KdNr)).value(QueryValue(nDX_KdNr));
    qbds.addRange(fieldnum(NDXKumUmsCustArtGrp, Jahr)).value(QueryValue(jahr));
    qbds.addRange(fieldnum(NDXKumUmsCustArtGrp, Companys)).value(QueryValue(firma));
    qr      = new QueryRun(q);
    while (qr.next())
    {
        nDX_KumUmsCustArtGrp = qr.get(tablenum(NDXKumUmsCustArtGrp));

        nDX_TmpCSAllianceArtGrp = NDXTmpCSAllianceArtGrp::find(l_NDX_TmpCSAlliance.UmsSignature,
                                                            l_NDX_TmpCSAlliance.MonthYearSignature,
                                                            lExclude,
                                                            l_NDX_TmpCSAlliance.Company,
                                                            l_NDX_TmpCSAlliance.Alliance,
                                                            l_NDX_TmpCSAlliance.CustAccount,
                                                            l_NDX_TmpCSAlliance.CentralStoreId,
                                                            nDX_KumUmsCustArtGrp.ArtGrp(),
                                                            true);

        nDX_TmpCSAllianceArtGrp.UmsSignature        = l_NDX_TmpCSAlliance.UmsSignature;
        nDX_TmpCSAllianceArtGrp.MonthYearSignature  = l_NDX_TmpCSAlliance.MonthYearSignature;
        nDX_TmpCSAllianceArtGrp.Exclude             = lExclude;
        nDX_TmpCSAllianceArtGrp.Company             = l_NDX_TmpCSAlliance.Company;
        nDX_TmpCSAllianceArtGrp.Alliance            = l_NDX_TmpCSAlliance.Alliance;
        nDX_TmpCSAllianceArtGrp.CustAccount         = l_NDX_TmpCSAlliance.CustAccount;
        nDX_TmpCSAllianceArtGrp.ArtGrp              = nDX_KumUmsCustArtGrp.ArtGrp();
        nDX_TmpCSAllianceArtGrp.CSDPctLfdJ          = l_NDX_TmpCSAlliance.CSDPctLfdJ;
        nDX_TmpCSAllianceArtGrp.CSDPctVJ            = l_NDX_TmpCSAlliance.CSDPctVJ;
        nDX_TmpCSAllianceArtGrp.CentralStoreId      = l_NDX_TmpCSAlliance.CentralStoreId;

        if (lAktJahr)
        {
            nDX_TmpCSAllianceArtGrp.U01         = (nDX_KumUmsCustArtGrp.Umsatz01 * nDX_TmpCSAllianceArtGrp.CSDPctLfdJ) / 100;
            nDX_TmpCSAllianceArtGrp.U02         = (nDX_KumUmsCustArtGrp.Umsatz02 * nDX_TmpCSAllianceArtGrp.CSDPctLfdJ) / 100;
            nDX_TmpCSAllianceArtGrp.U03         = (nDX_KumUmsCustArtGrp.Umsatz03 * nDX_TmpCSAllianceArtGrp.CSDPctLfdJ) / 100;
            nDX_TmpCSAllianceArtGrp.U04         = (nDX_KumUmsCustArtGrp.Umsatz04 * nDX_TmpCSAllianceArtGrp.CSDPctLfdJ) / 100;
            nDX_TmpCSAllianceArtGrp.U05         = (nDX_KumUmsCustArtGrp.Umsatz05 * nDX_TmpCSAllianceArtGrp.CSDPctLfdJ) / 100;
            nDX_TmpCSAllianceArtGrp.U06         = (nDX_KumUmsCustArtGrp.Umsatz06 * nDX_TmpCSAllianceArtGrp.CSDPctLfdJ) / 100;
            nDX_TmpCSAllianceArtGrp.U07         = (nDX_KumUmsCustArtGrp.Umsatz07 * nDX_TmpCSAllianceArtGrp.CSDPctLfdJ) / 100;
            nDX_TmpCSAllianceArtGrp.U08         = (nDX_KumUmsCustArtGrp.Umsatz08 * nDX_TmpCSAllianceArtGrp.CSDPctLfdJ) / 100;
            nDX_TmpCSAllianceArtGrp.U09         = (nDX_KumUmsCustArtGrp.Umsatz09 * nDX_TmpCSAllianceArtGrp.CSDPctLfdJ) / 100;
            nDX_TmpCSAllianceArtGrp.U10         = (nDX_KumUmsCustArtGrp.Umsatz10 * nDX_TmpCSAllianceArtGrp.CSDPctLfdJ) / 100;
            nDX_TmpCSAllianceArtGrp.U11         = (nDX_KumUmsCustArtGrp.Umsatz11 * nDX_TmpCSAllianceArtGrp.CSDPctLfdJ) / 100;
            nDX_TmpCSAllianceArtGrp.U12         = (nDX_KumUmsCustArtGrp.Umsatz12 * nDX_TmpCSAllianceArtGrp.CSDPctLfdJ) / 100;

            nDX_TmpCSAllianceArtGrp.C01         = (nDX_KumUmsCustArtGrp.CostAmount01 * nDX_TmpCSAllianceArtGrp.CSDPctLfdJ) / 100;
            nDX_TmpCSAllianceArtGrp.C02         = (nDX_KumUmsCustArtGrp.CostAmount02 * nDX_TmpCSAllianceArtGrp.CSDPctLfdJ) / 100;
            nDX_TmpCSAllianceArtGrp.C03         = (nDX_KumUmsCustArtGrp.CostAmount03 * nDX_TmpCSAllianceArtGrp.CSDPctLfdJ) / 100;
            nDX_TmpCSAllianceArtGrp.C04         = (nDX_KumUmsCustArtGrp.CostAmount04 * nDX_TmpCSAllianceArtGrp.CSDPctLfdJ) / 100;
            nDX_TmpCSAllianceArtGrp.C05         = (nDX_KumUmsCustArtGrp.CostAmount05 * nDX_TmpCSAllianceArtGrp.CSDPctLfdJ) / 100;
            nDX_TmpCSAllianceArtGrp.C06         = (nDX_KumUmsCustArtGrp.CostAmount06 * nDX_TmpCSAllianceArtGrp.CSDPctLfdJ) / 100;
            nDX_TmpCSAllianceArtGrp.C07         = (nDX_KumUmsCustArtGrp.CostAmount07 * nDX_TmpCSAllianceArtGrp.CSDPctLfdJ) / 100;
            nDX_TmpCSAllianceArtGrp.C08         = (nDX_KumUmsCustArtGrp.CostAmount08 * nDX_TmpCSAllianceArtGrp.CSDPctLfdJ) / 100;
            nDX_TmpCSAllianceArtGrp.C09         = (nDX_KumUmsCustArtGrp.CostAmount09 * nDX_TmpCSAllianceArtGrp.CSDPctLfdJ) / 100;
            nDX_TmpCSAllianceArtGrp.C10         = (nDX_KumUmsCustArtGrp.CostAmount10 * nDX_TmpCSAllianceArtGrp.CSDPctLfdJ) / 100;
            nDX_TmpCSAllianceArtGrp.C11         = (nDX_KumUmsCustArtGrp.CostAmount11 * nDX_TmpCSAllianceArtGrp.CSDPctLfdJ) / 100;
            nDX_TmpCSAllianceArtGrp.C12         = (nDX_KumUmsCustArtGrp.CostAmount12 * nDX_TmpCSAllianceArtGrp.CSDPctLfdJ) / 100;
        }
        else
        {
            nDX_TmpCSAllianceArtGrp.VU01        = (nDX_KumUmsCustArtGrp.Umsatz01 * nDX_TmpCSAllianceArtGrp.CSDPctVJ) / 100;
            nDX_TmpCSAllianceArtGrp.VU02        = (nDX_KumUmsCustArtGrp.Umsatz02 * nDX_TmpCSAllianceArtGrp.CSDPctVJ) / 100;
            nDX_TmpCSAllianceArtGrp.VU03        = (nDX_KumUmsCustArtGrp.Umsatz03 * nDX_TmpCSAllianceArtGrp.CSDPctVJ) / 100;
            nDX_TmpCSAllianceArtGrp.VU04        = (nDX_KumUmsCustArtGrp.Umsatz04 * nDX_TmpCSAllianceArtGrp.CSDPctVJ) / 100;
            nDX_TmpCSAllianceArtGrp.VU05        = (nDX_KumUmsCustArtGrp.Umsatz05 * nDX_TmpCSAllianceArtGrp.CSDPctVJ) / 100;
            nDX_TmpCSAllianceArtGrp.VU06        = (nDX_KumUmsCustArtGrp.Umsatz06 * nDX_TmpCSAllianceArtGrp.CSDPctVJ) / 100;
            nDX_TmpCSAllianceArtGrp.VU07        = (nDX_KumUmsCustArtGrp.Umsatz07 * nDX_TmpCSAllianceArtGrp.CSDPctVJ) / 100;
            nDX_TmpCSAllianceArtGrp.VU08        = (nDX_KumUmsCustArtGrp.Umsatz08 * nDX_TmpCSAllianceArtGrp.CSDPctVJ) / 100;
            nDX_TmpCSAllianceArtGrp.VU09        = (nDX_KumUmsCustArtGrp.Umsatz09 * nDX_TmpCSAllianceArtGrp.CSDPctVJ) / 100;
            nDX_TmpCSAllianceArtGrp.VU10        = (nDX_KumUmsCustArtGrp.Umsatz10 * nDX_TmpCSAllianceArtGrp.CSDPctVJ) / 100;
            nDX_TmpCSAllianceArtGrp.VU11        = (nDX_KumUmsCustArtGrp.Umsatz11 * nDX_TmpCSAllianceArtGrp.CSDPctVJ) / 100;
            nDX_TmpCSAllianceArtGrp.VU12        = (nDX_KumUmsCustArtGrp.Umsatz12 * nDX_TmpCSAllianceArtGrp.CSDPctVJ) / 100;

            nDX_TmpCSAllianceArtGrp.VC01        = (nDX_KumUmsCustArtGrp.CostAmount01 * nDX_TmpCSAllianceArtGrp.CSDPctVJ) / 100;
            nDX_TmpCSAllianceArtGrp.VC02        = (nDX_KumUmsCustArtGrp.CostAmount02 * nDX_TmpCSAllianceArtGrp.CSDPctVJ) / 100;
            nDX_TmpCSAllianceArtGrp.VC03        = (nDX_KumUmsCustArtGrp.CostAmount03 * nDX_TmpCSAllianceArtGrp.CSDPctVJ) / 100;
            nDX_TmpCSAllianceArtGrp.VC04        = (nDX_KumUmsCustArtGrp.CostAmount04 * nDX_TmpCSAllianceArtGrp.CSDPctVJ) / 100;
            nDX_TmpCSAllianceArtGrp.VC05        = (nDX_KumUmsCustArtGrp.CostAmount05 * nDX_TmpCSAllianceArtGrp.CSDPctVJ) / 100;
            nDX_TmpCSAllianceArtGrp.VC06        = (nDX_KumUmsCustArtGrp.CostAmount06 * nDX_TmpCSAllianceArtGrp.CSDPctVJ) / 100;
            nDX_TmpCSAllianceArtGrp.VC07        = (nDX_KumUmsCustArtGrp.CostAmount07 * nDX_TmpCSAllianceArtGrp.CSDPctVJ) / 100;
            nDX_TmpCSAllianceArtGrp.VC08        = (nDX_KumUmsCustArtGrp.CostAmount08 * nDX_TmpCSAllianceArtGrp.CSDPctVJ) / 100;
            nDX_TmpCSAllianceArtGrp.VC09        = (nDX_KumUmsCustArtGrp.CostAmount09 * nDX_TmpCSAllianceArtGrp.CSDPctVJ) / 100;
            nDX_TmpCSAllianceArtGrp.VC10        = (nDX_KumUmsCustArtGrp.CostAmount10 * nDX_TmpCSAllianceArtGrp.CSDPctVJ) / 100;
            nDX_TmpCSAllianceArtGrp.VC11        = (nDX_KumUmsCustArtGrp.CostAmount11 * nDX_TmpCSAllianceArtGrp.CSDPctVJ) / 100;
            nDX_TmpCSAllianceArtGrp.VC12        = (nDX_KumUmsCustArtGrp.CostAmount12 * nDX_TmpCSAllianceArtGrp.CSDPctVJ) / 100;
        }
        if (nDX_TmpCSAllianceArtGrp.validateWrite())
        {
            if (nDX_TmpCSAllianceArtGrp)
            {
                nDX_TmpCSAllianceArtGrp.write();
            }
            else
            {
                recordSortedList.ins(nDX_TmpCSAllianceArtGrp);
            }
        }
    }
    recordSortedList.insertDatabase();
    ttscommit;
}

/// <summary>
/// DebuC 16.10.23
/// </summary>
/// <param name = "l_NDX_KumUmsCustArtGrp">NDXKumUmsCustArtGrp</param>
/// <param name = "l_forUpdate">boolean</param>
/// <returns>NDXKumUmsCustArtGrp</returns>
client server static public NDXKumUmsCustArtGrp findOrCreate(NDXKumUmsCustArtGrp l_NDX_KumUmsCustArtGrp, boolean l_forUpdate = false)
{
    NDXKumUmsCustArtGrp      nDX_KumUmsCustArtGrp;
    nDX_KumUmsCustArtGrp = NDXKumUmsCustArtGrp::findRecord(l_NDX_KumUmsCustArtGrp, l_forUpdate);
    if (!nDX_KumUmsCustArtGrp.RecId)
    {
        nDX_KumUmsCustArtGrp = NDXKumUmsCustArtGrp::create(l_NDX_KumUmsCustArtGrp, l_forUpdate);
    }
    return nDX_KumUmsCustArtGrp;
}

/// <summary>
/// DebuC 16.10.23
/// </summary>
/// <param name = "l_NDX_KumUmsCustArtGrp">NDXKumUmsCustArtGrp</param>
/// <param name = "l_forUpdate">boolean</param>
/// <returns>NDXKumUmsCustArtGrp</returns>
client server static public NDXKumUmsCustArtGrp findRecord(NDXKumUmsCustArtGrp l_NDX_KumUmsCustArtGrp, boolean l_forUpdate = false)
{
    NDXKumUmsCustArtGrp   nDX_KumUmsCustArtGrp;
    ;
    if (l_forUpdate)
    {
        nDX_KumUmsCustArtGrp.selectForUpdate(l_forUpdate);
    }

    if (l_NDX_KumUmsCustArtGrp.CompanyId && l_NDX_KumUmsCustArtGrp.CustAccount && l_NDX_KumUmsCustArtGrp.Jahr)
    {
        select firstOnly    nDX_KumUmsCustArtGrp
            where           nDX_KumUmsCustArtGrp.CompanyId    == l_NDX_KumUmsCustArtGrp.CompanyId   &&
                            nDX_KumUmsCustArtGrp.CustAccount  == l_NDX_KumUmsCustArtGrp.CustAccount &&
                            nDX_KumUmsCustArtGrp.Jahr         == l_NDX_KumUmsCustArtGrp.Jahr        &&
                            nDX_KumUmsCustArtGrp.ARTGRP       == l_NDX_KumUmsCustArtGrp.ARTGRP;
    }
    else if (l_NDX_KumUmsCustArtGrp.KdNr && l_NDX_KumUmsCustArtGrp.Companys && l_NDX_KumUmsCustArtGrp.Jahr)
    {
        select firstOnly    nDX_KumUmsCustArtGrp
            where           nDX_KumUmsCustArtGrp.KdNr         == l_NDX_KumUmsCustArtGrp.KdNr        &&
                            nDX_KumUmsCustArtGrp.Companys     == l_NDX_KumUmsCustArtGrp.Companys    &&
                            nDX_KumUmsCustArtGrp.Jahr         == l_NDX_KumUmsCustArtGrp.Jahr        &&
                            nDX_KumUmsCustArtGrp.ARTGRP       == l_NDX_KumUmsCustArtGrp.ARTGRP;
    }

    return nDX_KumUmsCustArtGrp;
}

/// <summary>
/// DebuC 16.10.23
/// </summary>
/// <param name = "l_NDX_KumUmsCustArtGrp">NDXKumUmsCustArtGrp</param>
/// <param name = "l_forUpdate">boolean</param>
/// <returns>NDXKumUmsCustArtGrp</returns>
server static public NDXKumUmsCustArtGrp create(NDXKumUmsCustArtGrp l_NDX_KumUmsCustArtGrp, boolean l_forUpdate = false)
{
    NDXKumUmsCustArtGrp  nDX_KumUmsCustArtGrp;
    try
    {
        ttsbegin;
        nDX_KumUmsCustArtGrp.selectForUpdate(l_forUpdate);
        nDX_KumUmsCustArtGrp.CompanyId   = l_NDX_KumUmsCustArtGrp.CompanyId;
        nDX_KumUmsCustArtGrp.CustAccount = l_NDX_KumUmsCustArtGrp.CustAccount;
        nDX_KumUmsCustArtGrp.KdNr        = l_NDX_KumUmsCustArtGrp.KdNr;
        nDX_KumUmsCustArtGrp.Companys    = l_NDX_KumUmsCustArtGrp.Companys;
        nDX_KumUmsCustArtGrp.Jahr        = l_NDX_KumUmsCustArtGrp.Jahr;
        nDX_KumUmsCustArtGrp.ARTGRP      = l_NDX_KumUmsCustArtGrp.ARTGRP;
        nDX_KumUmsCustArtGrp.insert();
        ttscommit;
    }
    catch
    {
        throw Error(strfmt("@NDX:NDXKumUmsCustArtGrpNotCreated",  l_NDX_KumUmsCustArtGrp.KdNr));
    }

    return nDX_KumUmsCustArtGrp;
}

/// <summary>
/// DebuC 16.10.23
/// </summary>
/// <param name = "monat">NDXMonthBE</param>
void initUmsMonat(NDXMonthBE monat)
{
    ;
    switch (monat)
    {
        case NDXMonthBE::January   :   
            this.Umsatz01 = 0; 
            this.CostAmount01 = 0; 
            break;
        case NDXMonthBE::February  :   
            this.Umsatz02 = 0; 
            this.CostAmount02 = 0; 
            break;
        case NDXMonthBE::March     :   
            this.Umsatz03 = 0; 
            this.CostAmount03 = 0; 
            break;
        case NDXMonthBE::April     :   
            this.Umsatz04 = 0; 
            this.CostAmount04 = 0;
            break;
        case NDXMonthBE::May       :   
            this.Umsatz05 = 0; 
            this.CostAmount05 = 0;
            break;
        case NDXMonthBE::June      : 
            this.Umsatz06 = 0; 
            this.CostAmount06 = 0;
            break;
        case NDXMonthBE::July      :  
            this.Umsatz07 = 0; 
            this.CostAmount07 = 0;
            break;
        case NDXMonthBE::August    : 
            this.Umsatz08 = 0; 
            this.CostAmount08 = 0; 
            break;
        case NDXMonthBE::September :  
            this.Umsatz09 = 0; 
            this.CostAmount09 = 0;
            break;
        case NDXMonthBE::October   :   
            this.Umsatz10 = 0; 
            this.CostAmount10 = 0;
            break;
        case NDXMonthBE::November  :  
            this.Umsatz11 = 0;
            this.CostAmount11 = 0;
            break;
        case NDXMonthBE::December  : 
            this.Umsatz12 = 0;
            this.CostAmount12 = 0; 
            break;
    }

}

