/// <summary>
/// DebuC 16.10.23
/// </summary>
/// <returns>NDXUmsatz</returns>
NDXUmsatz getUmsJahr()
{
    NDXUmsatz      retWert;
    retWert =   this.Umsatz01 +
            this.Umsatz02 +
            this.Umsatz03 +
            this.Umsatz04 +
            this.Umsatz05 +
            this.Umsatz06 +
            this.Umsatz07 +
            this.Umsatz08 +
            this.Umsatz09 +
